-- The two acknowledgements of debt, and their covering emails.
-- Generated by scripts/letters/seed-aod.mjs --sql. Do not edit by hand; edit aod.mjs and
-- regenerate, or the document in the database stops matching the one in the repository.
-- Safe to run more than once, and it REMOVES NOTHING. See the note on adoption below.
begin;
-- ADOPTED, NOT DELETED, AND THE REASON IS A TOOL RATHER THAN A PREFERENCE.
--
-- This used to delete by seed key and by name before inserting, which is the ordinary way to
-- make a seed re-runnable. It could not be run: every DELETE sent through the session that
-- wrote it hung and rolled back -- proven against a temporary table created in the same
-- statement, so neither locks nor permissions -- and the file sat waiting for somebody to
-- paste it by hand for a week.
--
-- SO THE ONE ROW A DELETE WAS THERE TO CLEAR IS CLAIMED INSTEAD. The first attempt left an
-- "Acknowledgement of debt (individual)" with no seed key and format text; on the next line it
-- is given its key, which makes it the row the upsert below then overwrites in place. Without
-- this the insert would not collide on anything -- name is not unique -- and the Library would
-- show the firm two agreements with one name, one of them unusable.
--
-- NARROW ON PURPOSE: a letter, with that exact name, carrying no key. A row the firm has since
-- renamed is not adopted, because then the name is no longer evidence of where it came from.
update public.message_templates set seed_key = 'letter-aod-individual'
 where seed_key is null and kind = 'letter' and name = $q$Acknowledgement of debt (individual)$q$;
update public.message_templates set seed_key = 'letter-aod-company'
 where seed_key is null and kind = 'letter' and name = $q$Acknowledgement of debt (company)$q$;

-- AND THE SEED ITSELF IS AN UPSERT. seed_key is unique, so a second run overwrites the four
-- rows rather than making four more -- which is the whole of what the delete was buying.
insert into public.message_templates
  (scope, kind, name, subject, format, body, seed_key, audience, active)
values
  ($q$collections$q$, $q$letter$q$, $q$Acknowledgement of debt (individual)$q$, null, $q$document$q$, $q${"defaults":{"font":"\"Charter\", \"Bitstream Charter\", Georgia, serif","size":10.5,"colour":"#1f2937","lineHeight":1.45},"blocks":[{"kind":"table","borders":"none","widths":[28,72],"rows":[[{"spans":[{"text":"DATE","bold":true}]},{"spans":[{"text":"{{today}}"}]}],[{"spans":[{"text":"OUR REFERENCE","bold":true}]},{"spans":[{"text":"{{case_number}}"}]}],[{"spans":[{"text":"ACCOUNT","bold":true}]},{"spans":[{"text":"{{account_number}}"}]}],[{"spans":[{"text":"DELIVERY","bold":true}]},{"spans":[{"text":"By email, with notification by SMS"}]}]]},{"kind":"heading","level":1,"spans":[{"text":"ACKNOWLEDGEMENT OF DEBT"}]},{"kind":"paragraph","spans":[{"text":"Repayment agreement with consent to judgment"}]},{"kind":"paragraph","spans":[{"text":"between {{client_name}}, the creditor identified in item 1 of Part A (the “Creditor”), represented by {{firm_name}}, its duly authorised agent, and the debtor identified in item 3 of Part A (the “Debtor”)."}]},{"kind":"table","borders":"all","headerRow":true,"widths":[25,25,25,25],"keepTogether":true,"rows":[[{"spans":[{"text":"STEP 1","bold":true}]},{"spans":[{"text":"STEP 2","bold":true}]},{"spans":[{"text":"STEP 3","bold":true}]},{"spans":[{"text":"STEP 4","bold":true}]}],[{"spans":[{"text":"The debtor acknowledges the debt and waives all defences"}]},{"spans":[{"text":"The debtor pays the agreed instalments"}]},{"spans":[{"text":"On default the full balance becomes due at once"}]},{"spans":[{"text":"The creditor may lodge the signed consent to judgment"}]}]]},{"kind":"paragraph","spans":[{"text":"How this agreement works. It consists of Part A (particulars), Part B (terms and conditions) and Annexure A (consent to judgment). Every field in Part A must be completed before signature."}]},{"kind":"heading","level":2,"spans":[{"text":"WHY YOU ARE BEING ASKED TO SIGN THIS"}]},{"kind":"paragraph","spans":[{"text":"This agreement re