bt Collectors Act 114 of 1998."}]]},{"kind":"paragraph","spans":[{"text":"The Defendant confirms that this consent is given freely, that the Defendant has read and understood it, and that the Defendant has been advised of the right to obtain independent legal advice before signing."}]},{"kind":"spacer","mm":6},{"kind":"signature","widthMm":70,"signer":"debtor","spans":[{"text":"The Defendant — {{debtor_name}}"}]}]}$q$, $q$letter-aod-individual$q$, $q$individual$q$, true),
